package com.finsight;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.*;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.mock.mockito.MockBean;
import org.springframework.context.annotation.Import;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.context.*;
import org.springframework.test.web.servlet.MockMvc;
import java.math.BigDecimal;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import static com.finsight.SavingsModels.*;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest @AutoConfigureMockMvc @ActiveProfiles("test")
@ContextConfiguration(initializers=IsolatedDatabaseGuard.class) @Import(RecurringApiTest.TestClockConfig.class)
class SavingsApiTest {
 @Autowired SavingsService savings;@Autowired RecurringApiTest.MutableClock clock;@Autowired JdbcTemplate jdbc;@Autowired MockMvc mvc;@Autowired ObjectMapper json;@Autowired FinanceService finance;@Autowired ForecastService forecast;@Autowired SpendingService spending;@Autowired AssistantService assistant;@Autowired PlannedTransactionService plans;
 @MockBean SpendingAiClient ai;
 @BeforeEach void setup(){clean();clock.date("2026-10-15");jdbc.update("UPDATE accounts SET starting_balance=5000 WHERE id=?",DemoIdentity.ACCOUNT_ID);when(ai.analyze(any())).thenReturn(Optional.empty());}
 @AfterEach void clean(){for(String t:List.of("savings_corrections","savings_entries","savings_schedules","savings_goals","planned_transactions","forecast_preferences","recurring_prediction_feedback","recurring_occurrences","recurring_rules","category_prediction_feedback","category_predictions","transactions"))jdbc.update("DELETE FROM "+t);}
 UUID cat(String name){return jdbc.queryForObject("SELECT id FROM categories WHERE user_id=? AND name=?",UUID.class,DemoIdentity.USER_ID,name);}
 Detail goal(){return savings.create(new GoalInput("Vacation","Synthetic purpose",new BigDecimal("5000"),LocalDate.parse("2027-03-31"),UUID.randomUUID()));}
 EntryInput input(String amount,EntryType type,Bucket bucket,String date,UUID tx){return new EntryInput(new BigDecimal(amount),type,bucket,LocalDate.parse(date),"Synthetic allocation",tx);}
 Detail add(Detail d,String amount,EntryType type,Bucket bucket,String date){return savings.record(d.goal().id(),new EntryRequest(input(amount,type,bucket,date,null),UUID.randomUUID(),d.goal().version()));}
 ScheduleInput schedule(Detail d,String amount,RecurrenceFrequency f,int day){return new ScheduleInput(new BigDecimal(amount),Bucket.IN_ACCOUNT,f,day,f==RecurrenceFrequency.TWICE_MONTHLY?15:null,LocalDate.parse("2026-11-01"),null,true,LinkType.NONE,null,d.goal().version());}
 @Test void createRetryAndConflictingRequest(){UUID key=UUID.randomUUID();var i=new GoalInput("Vacation","Synthetic purpose",new BigDecimal("5000"),null,key);var a=savings.create(i);assertThat(savings.create(i).goal().id()).isEqualTo(a.goal().id());assertThat(a.goal().saved()).isEqualTo("0.00");assertThat(a.goal().createdAt()).isEqualTo(clock.instant());assertThatThrownBy(()->savings.create(new GoalInput("Other","",new BigDecimal("5000"),null,key))).hasMessageContaining("Request ID");}
 @Test void goalEditingPreservesEntriesAndOptimisticVersion(){var d=add(goal(),"500",EntryType.CONTRIBUTION,Bucket.IN_ACCOUNT,"2026-10-01");var before=d.entries();var r=savings.update(d.goal().id(),new GoalUpdate(new GoalInput("Trip","Edited",new BigDecimal("6000"),LocalDate.parse("2027-04-01"),d.goal().requestId()),d.goal().version()));assertThat(r.entries()).isEqualTo(before);assertThat(r.goal().name()).isEqualTo("Trip");assertThat(r.goal().saved()).isEqualTo("500.00");assertThatThrownBy(()->savings.update(d.goal().id(),new GoalUpdate(new GoalInput("Stale","",new BigDecimal("7000"),null,d.goal().requestId()),0L))).hasMessageContaining("Goal changed");}
 @Test void allocationAndWithdrawalNeverChangeActualCashOrForecastOrSpending(){var account=finance.account();var cash=forecast.forecast(LocalDate.parse("2027-01-01"));var report=spending.report(spending.period("this_month",null,null));var d=add(goal(),"500",EntryType.CONTRIBUTION,Bucket.IN_ACCOUNT,"2026-10-01");assertThat(d.goal().progress()).isEqualTo("10.00");d=add(d,"100",EntryType.WITHDRAWAL,Bucket.IN_ACCOUNT,"2026-10-02");assertThat(d.goal().saved()).isEqualTo("400.00");assertThat(d.goal().remaining()).isEqualTo("4600.00");assertThat(finance.account()).isEqualTo(account);assertThat(forecast.forecast(LocalDate.parse("2027-01-01"))).isEqualTo(cash);assertThat(spending.report(spending.period("this_month",null,null))).isEqualTo(report);assertThat(savings.dashboard().summary().unallocatedBalance()).isEqualTo("4600.00");}
 @Test void archivedReservationsAreRetainedAndRestorePreservesHistory(){var d=add(goal(),"100",EntryType.CONTRIBUTION,Bucket.IN_ACCOUNT,"2026-10-01");var archived=savings.state(d.goal().id(),new StateInput(Action.ARCHIVE,d.goal().version()));assertThat(archived.goal().status()).isEqualTo("ARCHIVED");assertThat(savings.dashboard().summary().allocatedInAccount()).isEqualTo("100.00");assertThatThrownBy(()->add(archived,"1",EntryType.CONTRIBUTION,Bucket.IN_ACCOUNT,"2026-10-02")).hasMessageContaining("Restore");var restored=savings.state(d.goal().id(),new StateInput(Action.RESTORE,archived.goal().version()));assertThat(restored.entries()).isEqualTo(d.entries());}
 @Test void completionRequiresTargetAndReopenBeforeWithdrawal(){var d=goal();final UUID initial=d.goal().id();assertThatThrownBy(()->savings.state(initial,new StateInput(Action.COMPLETE,0L))).hasMessageContaining("target");d=add(d,"5000",EntryType.CONTRIBUTION,Bucket.IN_ACCOUNT,"2026-10-01");var complete=savings.state(d.goal().id(),new StateInput(Action.COMPLETE,d.goal().version()));assertThat(complete.goal().completed()).isTrue();assertThatThrownBy(()->add(complete,"100",EntryType.WITHDRAWAL,Bucket.IN_ACCOUNT,"2026-10-02")).hasMessageContaining("reopen");var reopened=savings.state(d.goal().id(),new StateInput(Action.REOPEN,complete.goal().version()));assertThat(add(reopened,"100",EntryType.WITHDRAWAL,Bucket.IN_ACCOUNT,"2026-10-02").goal().saved()).isEqualTo("4900.00");}
 @Test void correctionRetainsOriginalReasonAndIsIdempotent(){var d=add(goal(),"500",EntryType.CONTRIBUTION,Bucket.IN_ACCOUNT,"2026-10-01");var e=d.entries().getFirst();UUID key=UUID.randomUUID();var c=new Correction(input("400",EntryType.CONTRIBUTION,Bucket.IN_ACCOUNT,"2026-10-01",null),"Synthetic typo",key,d.goal().version());var result=savings.correct(d.goal().id(),e.id(),c);assertThat(result.goal().saved()).isEqualTo("400.00");assertThat(result.entries()).hasSize(2);assertThat(result.entries()).anyMatch(x->!x.active()&&x.amount().equals("500.00")&&x.correctionReason().equals("Synthetic typo"));assertThat(savings.correct(d.goal().id(),e.id(),c)).isEqualTo(result);}
 @Test void voidEntryPreservesAuditAndRejectsNegativeHistoricalBuckets(){var d=add(goal(),"500",EntryType.CONTRIBUTION,Bucket.IN_ACCOUNT,"2026-10-01");var original=d.entries().getFirst();var voided=savings.correct(d.goal().id(),original.id(),new Correction(null,"Not a real allocation",UUID.randomUUID(),d.goal().version()));assertThat(voided.goal().saved()).isEqualTo("0.00");assertThat(voided.entries()).hasSize(1);var start=add(goal(),"500",EntryType.CONTRIBUTION,Bucket.IN_ACCOUNT,"2026-10-01");var withdrawn=add(start,"100",EntryType.WITHDRAWAL,Bucket.IN_ACCOUNT,"2026-10-02");assertThatThrownBy(()->savings.correct(start.goal().id(),start.entries().getFirst().id(),new Correction(null,"Wrong",UUID.randomUUID(),withdrawn.goal().version()))).hasMessageContaining("overdraw");assertThat(savings.detail(start.goal().id()).goal().saved()).isEqualTo("400.00");}
 @Test void backdatedWithdrawalCannotOverdrawEarlierDateOrAnotherBucket(){var d=add(goal(),"100",EntryType.CONTRIBUTION,Bucket.IN_ACCOUNT,"2026-10-10");assertThatThrownBy(()->add(d,"10",EntryType.WITHDRAWAL,Bucket.IN_ACCOUNT,"2026-10-01")).hasMessageContaining("overdraw");assertThatThrownBy(()->add(d,"10",EntryType.WITHDRAWAL,Bucket.EXTERNAL,"2026-10-12")).hasMessageContaining("overdraw");}
 @Test void exactDecimalProgressAndOverfunding(){var d=savings.create(new GoalInput("Small","",new BigDecimal("0.30"),null,UUID.randomUUID()));d=add(d,"0.10",EntryType.CONTRIBUTION,Bucket.IN_ACCOUNT,"2026-10-01");d=add(d,"0.20",EntryType.CONTRIBUTION,Bucket.IN_ACCOUNT,"2026-10-02");assertThat(d.goal().saved()).isEqualTo("0.30");assertThat(d.goal().progress()).isEqualTo("100.00");d=add(d,"0.10",EntryType.CONTRIBUTION,Bucket.IN_ACCOUNT,"2026-10-03");assertThat(d.goal().progress()).isEqualTo("133.33");assertThat(d.goal().remaining()).isEqualTo("0.00");}
 @Test void entryRetryDoesNotDoubleCountAndConcurrentRetryIsSerialized()throws Exception{var d=goal();var request=new EntryRequest(input("100",EntryType.CONTRIBUTION,Bucket.IN_ACCOUNT,"2026-10-01",null),UUID.randomUUID(),d.goal().version());try(var pool=Executors.newFixedThreadPool(2)){var gate=new CountDownLatch(1);var tasks=new ArrayList<Future<Detail>>();for(int i=0;i<2;i++)tasks.add(pool.submit(()->{gate.await();return savings.record(d.goal().id(),request);}));gate.countDown();for(var task:tasks)assertThat(task.get(15,TimeUnit.SECONDS).goal().saved()).isEqualTo("100.00");}assertThat(savings.detail(d.goal().id()).entries()).hasSize(1);}
 @Test void duplicateLinkedTransactionsAndRemovedReferencesRetainAudit(){var tx=finance.create(new ApiModels.TransactionInput("Synthetic deposit",new BigDecimal("500"),TransactionType.INCOME,cat("Salary"),LocalDate.parse("2026-10-01"),null));var d=goal();d=savings.record(d.goal().id(),new EntryRequest(input("500",EntryType.CONTRIBUTION,Bucket.IN_ACCOUNT,"2026-10-01",tx.id()),UUID.randomUUID(),d.goal().version()));var other=goal();assertThatThrownBy(()->savings.record(other.goal().id(),new EntryRequest(input("500",EntryType.CONTRIBUTION,Bucket.IN_ACCOUNT,"2026-10-01",tx.id()),UUID.randomUUID(),other.goal().version()))).hasMessageContaining("already linked");finance.delete(tx.id());var removed=savings.detail(d.goal().id());assertThat(removed.entries().getFirst().transactionMissing()).isTrue();assertThat(removed.entries().getFirst().transactionId()).isEqualTo(tx.id());assertThat(removed.goal().saved()).isEqualTo("500.00");}
 @Test void outboundTransferIsNotReservedFromLocalBalanceTwice(){var tx=finance.create(new ApiModels.TransactionInput("Synthetic outbound transfer",new BigDecimal("1000"),TransactionType.EXPENSE,cat("Other"),LocalDate.parse("2026-10-01"),null));var d=goal();d=savings.record(d.goal().id(),new EntryRequest(input("1000",EntryType.CONTRIBUTION,Bucket.EXTERNAL,"2026-10-01",tx.id()),UUID.randomUUID(),d.goal().version()));assertThat(d.goal().external()).isEqualTo("1000.00");assertThat(savings.dashboard().summary().actualBalance()).isEqualTo("4000.00");assertThat(savings.dashboard().summary().unallocatedBalance()).isEqualTo("4000.00");}
 @Test void linkedWholePaymentRequiresMatchingDirectionDateAndAmount(){var tx=finance.create(new ApiModels.TransactionInput("Synthetic deposit",new BigDecimal("100"),TransactionType.INCOME,cat("Salary"),LocalDate.parse("2026-10-01"),null));var d=goal();assertThatThrownBy(()->savings.record(d.goal().id(),new EntryRequest(input("99",EntryType.CONTRIBUTION,Bucket.IN_ACCOUNT,"2026-10-01",tx.id()),UUID.randomUUID(),0L))).hasMessageContaining("matching");assertThatThrownBy(()->savings.record(d.goal().id(),new EntryRequest(input("100",EntryType.CONTRIBUTION,Bucket.EXTERNAL,"2026-10-01",tx.id()),UUID.randomUUID(),0L))).hasMessageContaining("direction");}
 @ParameterizedTest @CsvSource({"DAILY,2026-11-02","WEEKLY,2026-11-08","BIWEEKLY,2026-11-15","TWICE_MONTHLY,2026-11-15","MONTHLY,2026-12-01","YEARLY,2027-11-01"})
 void allSixPlannedFrequenciesUseSharedRecurrence(String frequency,String completion){var d=savings.create(new GoalInput("Cadence","",new BigDecimal("200"),null,UUID.randomUUID()));d=savings.saveSchedule(d.goal().id(),schedule(d,"100",RecurrenceFrequency.valueOf(frequency),1));assertThat(d.projection().estimatedCompletionDate()).isEqualTo(LocalDate.parse(completion));assertThat(d.goal().saved()).isEqualTo("0.00");assertThat(finance.list()).isEmpty();}
 @Test void monthEndAndLeapYearSchedulesKeepAnchor(){var d=savings.create(new GoalInput("Leap","",new BigDecimal("300"),null,UUID.randomUUID()));d=savings.saveSchedule(d.goal().id(),new ScheduleInput(new BigDecimal("100"),Bucket.IN_ACCOUNT,RecurrenceFrequency.MONTHLY,31,null,LocalDate.parse("2027-01-31"),null,true,LinkType.NONE,null,0L));assertThat(d.projection().estimatedCompletionDate()).isEqualTo(LocalDate.parse("2027-03-31"));var yearly=savings.create(new GoalInput("Yearly","",new BigDecimal("200"),null,UUID.randomUUID()));yearly=savings.saveSchedule(yearly.goal().id(),new ScheduleInput(new BigDecimal("100"),Bucket.IN_ACCOUNT,RecurrenceFrequency.YEARLY,null,null,LocalDate.parse("2028-02-29"),null,true,LinkType.NONE,null,0L));assertThat(yearly.projection().estimatedCompletionDate()).isEqualTo(LocalDate.parse("2029-02-28"));}
 @Test void targetDateRequiredAmountsAndExpectedSavingsAreDeterministic(){var d=add(goal(),"400",EntryType.CONTRIBUTION,Bucket.IN_ACCOUNT,"2026-10-01");d=savings.saveSchedule(d.goal().id(),schedule(d,"500",RecurrenceFrequency.MONTHLY,1));assertThat(d.projection().expectedByTarget()).isEqualTo("2900.00");assertThat(d.projection().requiredMonthly()).isEqualTo("766.67");assertThat(d.projection().requiredPerOccurrence()).isEqualTo("920.00");assertThat(d.projection().estimatedCompletionDate()).isEqualTo(LocalDate.parse("2027-08-01"));assertThat(d.projection().bankProjectedBalance()).isEqualTo("5000.00");}
 @Test void insufficientHistoryAbstainsAndThreeCompleteMonthsSupportEstimate(){var d=goal();assertThat(d.projection().estimatedCompletionDate()).isNull();assertThat(d.projection().method()).isEqualTo("insufficient_history");for(String date:List.of("2026-07-01","2026-08-01","2026-09-01"))d=add(d,"100",EntryType.CONTRIBUTION,Bucket.IN_ACCOUNT,date);assertThat(d.projection().method()).isEqualTo("historical_monthly_net");assertThat(d.projection().estimatedCompletionDate()).isNotNull();assertThat(d.projection().months()).hasSize(3);}
 @Test void staleScheduleDoesNotBackfillAndDisabledOrExpiredPlanDoesNotInventCompletion(){var d=goal();d=savings.saveSchedule(d.goal().id(),schedule(d,"100",RecurrenceFrequency.MONTHLY,1));clock.date("2027-01-15");var now=savings.detail(d.goal().id());assertThat(now.goal().saved()).isEqualTo("0.00");assertThat(now.projection().points().stream().filter(p->p.projected()!=null&&p.date().isAfter(clock.instant().atZone(clock.getZone()).toLocalDate())).findFirst().orElseThrow().date()).isEqualTo(LocalDate.parse("2027-02-01"));}
 @Test void explicitlyLinkedPlanHasOneCashEffectAndOneAllocationEffect(){var plan=plans.create(new ForecastModels.PlanInput("Synthetic transfer",new BigDecimal("500"),TransactionType.EXPENSE,cat("Other"),LocalDate.parse("2026-11-01"),UUID.randomUUID()));var baseline=forecast.forecast(LocalDate.parse("2027-10-15"));var d=savings.create(new GoalInput("Transfer goal","",new BigDecimal("500"),LocalDate.parse("2026-12-01"),UUID.randomUUID()));d=savings.saveSchedule(d.goal().id(),new ScheduleInput(new BigDecimal("500"),Bucket.EXTERNAL,null,null,null,LocalDate.parse("2026-10-16"),null,true,LinkType.PLANNED,plan.id(),0L));assertThat(d.projection().estimatedCompletionDate()).isEqualTo(LocalDate.parse("2026-11-01"));assertThat(d.projection().bankProjectedBalance()).isEqualTo("4500.00");assertThat(forecast.forecast(LocalDate.parse("2027-10-15"))).isEqualTo(baseline);assertThat(finance.account().balance()).isEqualByComparingTo("5000");}
 @Test void aWholeFutureTransferCannotFundTwoGoalForecasts(){var p=plans.create(new ForecastModels.PlanInput("Synthetic shared transfer",new BigDecimal("500"),TransactionType.EXPENSE,cat("Other"),LocalDate.parse("2026-11-01"),UUID.randomUUID()));var a=goal();savings.saveSchedule(a.goal().id(),new ScheduleInput(new BigDecimal("500"),Bucket.EXTERNAL,null,null,null,LocalDate.parse("2026-10-16"),null,true,LinkType.PLANNED,p.id(),0L));var b=goal();assertThatThrownBy(()->savings.saveSchedule(b.goal().id(),new ScheduleInput(new BigDecimal("500"),Bucket.EXTERNAL,null,null,null,LocalDate.parse("2026-10-16"),null,true,LinkType.PLANNED,p.id(),0L))).hasMessageContaining("already associated");}
 @Test void readOnlyAssistantUsesSavedTotalsAndAsksForAmbiguousGoals(){var d=add(goal(),"400",EntryType.CONTRIBUTION,Bucket.IN_ACCOUNT,"2026-10-01");var before=jdbc.queryForList("SELECT * FROM savings_goals");var a=assistant.ask(new AssistantModels.Question("How much have I saved toward my vacation?",null));assertThat(a.status()).isEqualTo("answered");assertThat(a.text()).contains("400.00","4600.00");assertThat(a.links()).anyMatch(l->l.href().equals("#savings"));assertThat(assistant.ask(new AssistantModels.Question("When will I reach my savings goal?",null)).text()).contains("No supported completion");assertThat(jdbc.queryForList("SELECT * FROM savings_goals")).isEqualTo(before);goal();assertThat(assistant.ask(new AssistantModels.Question("How much have I saved toward my vacation?",null)).status()).isEqualTo("clarification");}
 @Test void assistantClosestAndMonthlyQuestionsAreGrounded(){var d=add(goal(),"500",EntryType.CONTRIBUTION,Bucket.IN_ACCOUNT,"2026-10-01");var a=assistant.ask(new AssistantModels.Question("Which savings goal is closest to completion?",null));assertThat(a.text()).contains("500.00");assertThat(assistant.ask(new AssistantModels.Question("How much should I save each month to reach my target?",null)).status()).isEqualTo("answered");assertThat(assistant.ask(new AssistantModels.Question("How much should I save each month for my Vacation?",null)).metrics()).anyMatch(m->m.label().endsWith("required monthly")&&m.value().equals("750.00"));assertThat(assistant.ask(new AssistantModels.Question("Create a savings goal",null)).status()).isEqualTo("unsupported");}
 @ParameterizedTest @ValueSource(strings={"0","-1","1.001","1000000000000"}) void invalidMoneyNeverWrites(String amount){assertThatThrownBy(()->savings.create(new GoalInput("Invalid","",new BigDecimal(amount),null,UUID.randomUUID()))).hasMessageContaining("positive money");assertThat(savings.list()).isEmpty();}
 @Test void pausedSchedulesAndTwiceMonthlyClampingDoNotInventDeposits(){var d=savings.create(new GoalInput("Clamp","",new BigDecimal("200"),null,UUID.randomUUID()));d=savings.saveSchedule(d.goal().id(),new ScheduleInput(new BigDecimal("100"),Bucket.IN_ACCOUNT,RecurrenceFrequency.TWICE_MONTHLY,30,31,LocalDate.parse("2027-02-01"),null,true,LinkType.NONE,null,0L));assertThat(d.projection().estimatedCompletionDate()).isEqualTo(LocalDate.parse("2027-03-30"));clock.date("2027-03-15");d=savings.saveSchedule(d.goal().id(),new ScheduleInput(new BigDecimal("100"),Bucket.IN_ACCOUNT,RecurrenceFrequency.TWICE_MONTHLY,30,31,LocalDate.parse("2027-02-01"),null,false,LinkType.NONE,null,d.goal().version()));assertThat(d.projection().estimatedCompletionDate()).isNull();assertThat(d.projection().method()).isEqualTo("paused_schedule");assertThat(d.goal().saved()).isEqualTo("0.00");}
 @Test void recurringCashLinkCountsOnlyPendingMatchingOccurrences(){var id=UUID.randomUUID();jdbc.update("INSERT INTO recurring_rules(id,user_id,account_id,category_id,description,amount,type,frequency,payment_day,start_date,next_date,enabled,archived,request_id,creation_fingerprint,created_at,version) VALUES (?,?,?,?,?,500,'EXPENSE','MONTHLY',1,DATE '2026-11-01',DATE '2026-11-01',TRUE,FALSE,?,?,CURRENT_TIMESTAMP,0)",id,DemoIdentity.USER_ID,DemoIdentity.ACCOUNT_ID,cat("Other"),"Synthetic recurring transfer",UUID.randomUUID(),"synthetic");var d=savings.create(new GoalInput("Recurring link","",new BigDecimal("1000"),null,UUID.randomUUID()));d=savings.saveSchedule(d.goal().id(),new ScheduleInput(new BigDecimal("500"),Bucket.EXTERNAL,null,null,null,LocalDate.parse("2026-10-16"),null,true,LinkType.RECURRING,id,0L));assertThat(d.projection().estimatedCompletionDate()).isEqualTo(LocalDate.parse("2026-12-01"));jdbc.update("UPDATE recurring_rules SET enabled=FALSE WHERE id=?",id);assertThat(savings.detail(d.goal().id()).projection().estimatedCompletionDate()).isNull();assertThat(finance.list()).isEmpty();}
 @Test void foreignGoalsAndCashLinksAreNeverAccessible(){var other=UUID.randomUUID();jdbc.update("INSERT INTO users(id,email,display_name) VALUES (?,?,?)",other,"synthetic-"+other+"@example.test","Synthetic owner");var account=UUID.randomUUID();jdbc.update("INSERT INTO accounts(id,user_id,name) VALUES (?,?,?)",account,other,"Synthetic account");var foreign=UUID.randomUUID();jdbc.update("INSERT INTO savings_goals(id,user_id,account_id,name,target_amount,created_at,request_id,creation_fingerprint) VALUES (?,?,?,?,100,CURRENT_TIMESTAMP,?,?)",foreign,other,account,"Foreign",UUID.randomUUID(),"synthetic");assertThat(savings.list()).isEmpty();assertThatThrownBy(()->savings.detail(foreign)).hasMessageContaining("not found");jdbc.update("DELETE FROM savings_goals WHERE id=?",foreign);jdbc.update("DELETE FROM accounts WHERE id=?",account);jdbc.update("DELETE FROM users WHERE id=?",other);}
 @Test void apiInputValidationAndOwnership()throws Exception{mvc.perform(post("/api/savings-goals").contentType("application/json").content("{\"name\":\"Invalid\",\"targetAmount\":\"-1\",\"requestId\":\""+UUID.randomUUID()+"\"}")).andExpect(status().isBadRequest());mvc.perform(get("/api/savings-goals/"+UUID.randomUUID())).andExpect(status().isNotFound());mvc.perform(post("/api/savings-goals").header("Origin","https://outside.invalid").contentType("application/json").content("{}")).andExpect(status().isForbidden());mvc.perform(get("/api/savings-goals")).andExpect(jsonPath("$.summary.actualBalance").value("5000.00"));}
}
